param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$files=@{policy='AIConflictCore/Scripts/Game/AIConflict/Vehicles/AICF_VehicleGarbagePolicy.c';fleet='AIConflictCore/Scripts/Game/AIConflict/State/Vehicles/AICF_FactionFleet.c';lease='AIConflictCore/Scripts/Game/AIConflict/State/Vehicles/AICF_VehicleLease.c';trace='AIConflictCore/Scripts/Game/AIConflict/Diagnostics/AICF_GroupTrace.c';client='tests/fixtures/AICF_VehiclePresetClientProbe.c'}
$sources=@{};foreach($key in $files.Keys){$sources[$key]=[IO.File]::ReadAllText((Join-Path $RepositoryRoot $files[$key]))}
function Body($s,$m){Get-AICFMethodBody ([pscustomobject]@{Source=$s;Code=(ConvertTo-AICFCodeText $s)}) $m}
function Rules($set){
 $p=$set.policy;$identity=Body $p 'MatchesPhysicalIdentity';$captured=Body $p 'MatchesCapturedEntity';$current=Body $p 'CanProtect';$stop=Body $p 'Stop';$register=Body $p 'Register';$insert=Body $p 'OnInsertRequested';$delete=Body $p 'OnBeforeDelete'
 foreach($part in @('!Replication.IsServer()','!entity.GetWorld()','entity != m_Vehicle','entity.GetID() != m_EntityId','m_EntityId == EntityID.INVALID','IsAuthoritativeReplicatedEntity(entity)','ComponentRpl(entity) != m_sRpl')){if(!$captured.Contains($part)){'IMMUTABLE_CAPTURED_PHYSICAL_AUTHORITY';break}}
 foreach($part in @('!MatchesCapturedEntity(entity)','!m_Lease','!m_Fleet','m_Lease.GetVehicle() == m_Vehicle','m_Lease.MatchesIdentity(m_sFaction, m_iSlot, m_iGroup,','m_iLease, m_iVehicle, m_EntityId, m_sRpl)','m_Lease.MatchesTripIdentity(m_sFaction, m_iSlot, m_iGroup, m_iTrip)')){if(!$identity.Contains($part)){'IMMUTABLE_OWNER_IDENTITY';break}}
 foreach($part in @('!m_bStopped','MatchesPhysicalIdentity(entity)','m_Fleet.OwnsVehicleLease(m_Lease)','m_Lease.IsCapActive()')){if(!$current.Contains($part)){'CURRENT_CAP_HELD_PERMISSION';break}}
 if($current -match 'AICF_EVehicleLeaseState\.ACTIVE|HasPhysicalAsset|GetDamageState|IsAliveCharacter'){'NO_PREMATURE_RELEASE_OR_WRECK_BYPASS'}
 if(!$p.Contains('static ref array<AICF_VehicleGarbagePermission>') -or $p -match 'array<ref AICF_VehicleGarbagePermission>'){ 'WEAK_STATIC_REGISTRY' }
 if(!$set.lease.Contains('protected ref AICF_VehicleGarbagePermission m_GarbagePermission')){'LEASE_STRONG_PERMISSION_OWNER'}
