 if(!$register.Contains('!Replication.IsServer()') -or !$register.Contains('!fleet.OwnsVehicleLease(lease)') -or !$register.Contains('!permission.CanProtect(lease.GetVehicle())')){'GUARDED_REGISTRATION'}
 if(!$stop.Contains('m_bStopped = true;') -or !$stop.Contains('AICF_VehicleGarbagePolicy.Unregister(this)') -or $stop.IndexOf('Unregister(this)') -gt $stop.IndexOf('garbage.Insert(m_Vehicle)')){'REMOVE_BEFORE_NATIVE_RESTORE'}
 foreach($part in @('!m_bEndedTracking','!MatchesCapturedEntity(m_Vehicle)','AICF_VehicleGarbagePolicy.Find(m_Vehicle)','garbage.IsInserted(m_Vehicle)','garbage.Insert(m_Vehicle)')){if(!$stop.Contains($part)){'RESTORE_ONLY_OWN_VETO_EXACT_ASSET';break}}
 if($stop.Contains('m_Lease') -or $stop.Contains('m_Fleet') -or $stop.Contains('MatchesPhysicalIdentity(')){'RESTORE_WITHOUT_DEAD_WEAK_OWNER'}
 $release=Body $set.lease 'RelinquishReleasedVehicleReference'
 if(!$release.Contains('m_GarbagePermission.Stop()') -or $release.IndexOf('m_GarbagePermission.Stop()') -gt $release.IndexOf('m_Vehicle = null;')){'RESTORE_BEFORE_TRANSFER_POINTER_CLEAR'}
 foreach($method in @('BeginRelease','BeginRetainedRelease','FailClosed')){if((Body $set.lease $method).Contains('m_GarbagePermission.Stop')){'NO_NATIVE_GC_BEFORE_SAFE_RELEASE'} }
 foreach($body in @($insert,$delete)){if(!$body.Contains('AICF_VehicleGarbagePolicy.Find(entity)') -or !$body.Contains('permission.RecordVeto(') -or $body.IndexOf('permission.RecordVeto(') -gt $body.IndexOf('super.')){'OWNED_SHORT_CIRCUIT_BEFORE_NATIVE_RESOURCE_SUBSCRIPTIONS';break}}
 if(([regex]::Matches($insert,'super.OnInsertRequested\(entity, lifetime\)')).Count -ne 1 -or ([regex]::Matches($delete,'super.OnBeforeDelete\(entity\)')).Count -ne 1 -or !$insert.Contains('return -1;') -or !$delete.Contains('return false;')){'STOCK_CALLBACK_CHAIN_EXACTLY_ONCE'}
 if((ConvertTo-AICFCodeText $p) -match '\b(?:UpdateBlacklist|Withdraw|Flush|CallLater|SetHealth|SetLifeState|Teleport)\s*\('){'NO_BLACKLIST_GLOBAL_GC_OR_GAMEPLAY_MUTATION'}
 foreach($part in @('garbage.IsInserted(vehicle)','garbage.GetLifetime(vehicle)','garbage.GetRemainingLifetime(vehicle)','gc_permission_current=','gc_veto_ended_tracking=')){if(!$p.Contains($part)){'NATIVE_GC_LIFETIME_TELEMETRY';break}}
 if(!$set.trace.Contains('AICF_VehicleGarbagePolicy.Describe(vehicle)')){'FULL_SOAK_BEFORE_GC_TELEMETRY'}
 $clientRun=Body $set.client 'Run';$clientBind=Body $set.client 'AICF_ClientGCBind'
 foreach($part in @('!Replication.IsServer()','component.IsProxy() && !component.IsMaster()','component.Id() == expected && Replication.FindItem(expected) == component','fleet.OwnsVehicleLease(lease)','lease.HasPhysicalAsset()','lease.MatchesIdentity("USSR", 0, 1,','lease.MatchesTripIdentity("USSR", 0, 1, 17)','!AICF_VehicleGarbagePolicy.Register(fleet, lease)','new AICF_VehicleGarbagePermission(fleet, lease)','!permission.CanProtect(vehicle)','[AICF][VEHICLE_UI_GC_AUTHORITY]')){if(!$clientRun.Contains($part)){'ACTUAL_CLIENT_REALM_AND_MATCHED_NATIVE_INPUTS';break}}
 if(!$clientBind.Contains('Replication.IsServer()') -or !$clientBind.Contains('m_aLeases.Insert(lease)') -or !$clientBind.Contains('BindReservedLeaseVehicle(lease, vehicle, rpl,')){ 'PRIVATE_CLIENT_FLEET_SETUP_ONLY' }
 $serverEnabled=Body $set.client 'AICF_VehicleGCProbeServerEnabled';$serverSpawn=Body $set.client 'RpcAsk_AICFVehicleGCProbe';$resolve=Body $set.client 'AICF_VehicleGCProbeEntity';$cleanup=Body $set.client 'AICF_VehicleGCProbeCleanup';$safeDelete=Body $set.client 'AICF_VehicleGCProbeSafeDelete';$tick=Body $set.client 'Tick'
 $clientRequest=Body $set.client 'AICF_RequestVehicleGCProbe'
 if(!$tick.Contains('[AICF][VEHICLE_UI_GC_CLIENT_TICK]') -or !$clientRequest.Contains('[AICF][VEHICLE_UI_GC_CLIENT_REQUEST]') -or !$clientRequest.Contains('[AICF][VEHICLE_UI_GC_CLIENT_SEND]') -or $clientRequest.IndexOf('VEHICLE_UI_GC_CLIENT_REQUEST') -gt $clientRequest.IndexOf('if (Replication.IsServer()')){'RPC_CLIENT_GUARD_RECEIPT_BEFORE_RETURN'}
