 $serverGuard=[regex]::Match($serverEnabled,'(?s)return Replication\.IsServer\(\).*?;').Value
 foreach($part in @('Replication.IsServer()','hasClientFlag && clientFlag == "1"','hasBehaviorFlag && behaviorFlag == "1"','GetPlayerId() > 0','manager.GetPlayerController(GetPlayerId()) == this')){if(!$serverGuard.Contains($part)){'SERVER_RPC_EXACT_OWNED_CONTROLLER_CLI_AUTHORITY';break}}
 if($serverGuard.Contains('IsAuthoritativeReplicatedEntity(this)')){'PLAYER_CONTROLLER_CONNECTION_AUTHORITY_NOT_VEHICLE_COMPONENT_ROLE'}
 foreach($part in @('!AICF_VehicleGCProbeServerEnabled()','GetPlayerIdFromControlledEntity(avatar) != GetPlayerId()','"WAIT_AVATAR", false','!m_bAICFGCProbeSpawnAttempted','m_bAICFGCProbeSpawnAttempted = true','FindEmptyTerrainPosition','distance < 10 || distance > 20','TryGetWaterSurfaceSimple','SpawnEntityPrefab(prefab, world, params)','m_AICFGCProbeVehicle.GetID() != m_AICFGCProbeVehicleId','!component.IsMaster() || component.IsProxy()')){if(!$serverSpawn.Contains($part)){'SERVER_EMPTY_NATIVE_SPAWN_ONCE_IDENTITY_GUARDS';break}}
 foreach($part in @('world.QueryEntitiesBySphere(position + "0 0.2 0", 5, AICF_VehicleGCProbeCollectNearby, null, EQueryEntitiesFlags.ALL)','if (m_bAICFGCProbeNearbyCharacter) continue;')){if(!$serverSpawn.Contains($part)){'SPAWN_CANDIDATE_USES_SAME_NATIVE_CHARACTER_CLEARANCE';break}}
 if($serverSpawn.IndexOf('world.QueryEntitiesBySphere(position + "0 0.2 0"') -gt $serverSpawn.IndexOf('safe = true;')){'SPAWN_CHARACTER_CLEARANCE_BEFORE_ACCEPTING_CANDIDATE'}
 if(!$resolve.Contains('Replication.FindItem(m_AICFGCProbeClientRpl)') -or !$resolve.Contains('component.GetEntity()') -or $clientRun.Contains('DeleteEntity') -or $clientRun.Contains('SpawnEntity')){'ONLY_REAL_STREAMED_CLIENT_PROXY_NO_CLIENT_MUTATION'}
 foreach($part in @('vehicle.GetID() != m_AICFGCProbeVehicleId','component.Id() != m_AICFGCProbeServerRpl','seats.IsEmpty()','!seat || seat.GetOccupant()','QueryEntitiesBySphere','m_bAICFGCProbeNearbyCharacter','GetVehicleIn(actor) == vehicle','CanDeleteVehicle(vehicle)')){if(!$safeDelete.Contains($part)){'SERVER_EXACT_EMPTY_ONLY_CLEANUP';break}}
 foreach($part in @('if (!GetGame()) return false;','BaseWorld world = GetGame().GetWorld();','PlayerManager manager = GetGame().GetPlayerManager();','if (!world || !manager) return false;','manager.GetPlayerIdFromControlledEntity(vehicle)','manager.GetPlayers(players)','manager.GetPlayerController(playerId)')){if(!$safeDelete.Contains($part)){'TEARDOWN_UNAVAILABLE_NATIVE_SERVICES_FAIL_CLOSED';break}}
 if($safeDelete.IndexOf('if (!GetGame()) return false;') -gt $safeDelete.IndexOf('GetGame().GetWorld()') -or $safeDelete.IndexOf('if (!world || !manager) return false;') -gt $safeDelete.IndexOf('manager.GetPlayerIdFromControlledEntity(vehicle)') -or ([regex]::Matches($safeDelete,'GetGame\(\).GetPlayerManager\(\)')).Count -ne 1){'TEARDOWN_GUARD_BEFORE_SINGLE_MANAGER_DEREFERENCE'}
 if(([regex]::Matches($cleanup,'!AICF_VehicleGCProbeSafeDelete\(\)')).Count -ne 2 -or !$cleanup.Contains('RplComponent.DeleteRplEntity(vehicle, false)')){'REPEAT_OCCUPANCY_BEFORE_NATIVE_DELETE'}
 if(!$tick.Contains('m_bProbeBehaviorSettings && !m_bProbeGarbageChecked') -or !$tick.Contains('if (!m_Player.AICF_VehicleGCProbeReady()) return;') -or !$tick.Contains('Check("GC_NO_AUTHORITY_REJECTED", AICF_VehicleClientGarbageProbe.Run(') -or !$tick.Contains('m_bProbeGarbageChecked = true;')){'REQUIRED_CLIENT_JIP_AUTHORITY_CASE'}
 if(!$clientRun.Contains('actor_present=') -or !$clientRun.Contains('lease_state=') -or !$serverSpawn.Contains('resource_valid=') -or !$serverSpawn.Contains('safe_spawn=')){'ACTUAL_SETUP_DIAGNOSTICS'}
}
$bad=@(Rules $sources);if($bad.Count){throw ($bad -join ',')}
$mutants=@(
