 @('policy','!Replication.IsServer()','false'),@('policy','!AICF_VehicleBoardingMutationFence.IsAuthoritativeReplicatedEntity(entity)','false'),@('policy','entity != m_Vehicle','false'),@('policy','entity.GetID() != m_EntityId','false'),
 @('policy','ComponentRpl(entity) != m_sRpl','false'),@('policy','m_iLease, m_iVehicle, m_EntityId, m_sRpl)','m_iLease, m_iVehicle, EntityID.INVALID, m_sRpl)'),
